### C++

```cpp
#include <bits/stdc++.h>
using namespace std;

struct Edge {
    int to, w;
};

int n, k;
vector<vector<Edge>> g;

pair<int, int> dfs(int u, int p, int L) {
    int dp0 = 0; // 不修改 u 的频率
    int dp1 = 1; // 修改 u 的频率
    for (const auto &e : g[u]) {
        int v = e.to, w = e.w;
        if (v == p) continue;
        auto [c0, c1] = dfs(v, u, L);
        if (w > L) {                 // 坏边
            dp0 += c1;               // 不修改 u 必改 v
            dp1 += min(c0, c1);      // 修改 u，v 任意
        } else {                     // 好边
            int t = min(c0, c1);
            dp0 += t;
            dp1 += t;
        }
    }
    return {dp0, dp1};
}

bool check(int L) {
    auto [dp0, dp1] = dfs(1, 0, L);
    return min(dp0, dp1) <= k;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> k;
    vector<int> f(n + 1);
    for (int i = 1; i <= n; i++) cin >> f[i];

    g.assign(n + 1, {});
    int maxw = 0;
    for (int i = 0; i < n - 1; i++) {
        int u, v;
        cin >> u >> v;
        int w = abs(f[u] - f[v]);
        maxw = max(maxw, w);
        g[u].push_back({v, w});
        g[v].push_back({u, w});
    }

    int lo = 0, hi = maxw;
    while (lo < hi) {
        int mid = (lo + hi) / 2;
        if (check(mid)) hi = mid;
        else lo = mid + 1;
    }
    cout << lo << "\n";
    return 0;
}
